// src/pages/page.js
import React from "react"
import { graphql } from "gatsby"

import Bio from "../components/bio"
import Layout from "../components/layout"
import Seo from "../components/seo"
import Share from "../components/share"

const BlogIndex = ({ data, location }) => {
  const siteTitle = data.site.siteMetadata?.title || `Title`
  const posts = data.allFile.edges
  const topurl="https://kyukyunyorituryo.github.io/bookshelf/"
  return (
      <Layout location={location} title={siteTitle}>



                  <h1 class="main-heading">kobo用EPUBファイルの一覧</h1>
                  <ol style={{ listStyle: `none` }}>
        {posts.map(post => {

          return (
            <li key={post.node.name}>
              <article
                className="post-list-item"
                itemScope
                itemType="http://schema.org/Article"
              >
                <header>
                  <h2>
                    <a href={`${topurl}kepub/${post.node.name}.epub`} itemProp="url">
                      <span itemProp="headline">{post.node.name}</span>
                    </a>
                  </h2>
                  <small>{post.node.modifiedTime}</small>

                </header>
              </article>
            </li>
          )
        })}
      </ol>
        <Share
          title={siteTitle}
          url={`${data.site.siteMetadata.siteUrl}`}
          />
            <Bio />
          </Layout>
  )
}

export default BlogIndex

/**
 * Head export to define metadata for the page
 *
 * See: https://www.gatsbyjs.com/docs/reference/built-in-components/gatsby-head/
 */
export const Head = () => <Seo title="青空文庫をEPUBやmobiに変換したものをおいている本棚" />

export const pageQuery = graphql`
query MyQuery {
  site {
    siteMetadata {
      title
      siteUrl
    }
  }
  allFile(
    filter: {extension: {eq: "epub"}, name: {regex: "/^.*(kepub)$/"}}
    sort: {modifiedTime: DESC}
  ) {
    edges {
      node {
        name
        modifiedTime(formatString: "YYYY年MM月DD日")
      }
    }
  }
}
`
